    private void PutConfront(int player,JsonObject c)=>SaveConfronts(player,Confronts(player).Where(n=>S(n,"npc")!=S(c,"npc")).Append(c));
    private void DropConfront(int player,string id)=>SaveConfronts(player,Confronts(player).Where(c=>S(c,"npc")!=id));
