            offered=new(){[S(d,"thing")=="purse"?"I'm sorry. Here, it's all there.":"I'm sorry. Here, take it back."]="sorry",["Mind your own business."]="leave"};if(Money(player)>=offer)offered[$"Here's {offer} centimes. Let's forget it."]="bribe";c["offered"]=offered;PutConfront(player,c);return Line(B(c,"owner")?$"That's my {S(Data["things"]?[S(d,"thing")],"noun")}. What do you think you're doing?":"I saw what you did. That is not yours.",offered);
