            int priors=C.Rows("SELECT owner,witnesses FROM deed WHERE player_id=$p0 AND id!=$p1 AND seen=1",player,(int)N(d,"id")).Count(row=>S(row,"owner")==id||A(JsonNode.Parse(S(row,"witnesses","[]"))).Any(n=>n?.GetValue<string>()==id));double chance=ForgiveChance(N(stats,"warmth",5),N(stats,"temper",5),C.Scalar<int>("SELECT trust FROM npc_relationship WHERE npc_id=$p0 AND player_id=$p1",id,player),Charisma(player),severity,priors,B(c,"owner"))*(held?1:.5);
