    }
    private void Forgive(int player,JsonObject c,JsonObject d){C.Execute("UPDATE deed SET status='forgiven',rumour_at=NULL,quiet=0 WHERE id=$p0",(int)N(d,"id"));Trust(player,S(c,"npc"),-1);Memory(player,S(c,"npc"),"Jef took what was not his, then said sorry and gave it back. I let it go, this once.",5);C.Log(player,"forgiven",S(c,"npc"),Name(S(c,"npc"))+" let Jef off over a theft.");DropConfront(player,S(c,"npc"));}
    private void Escalate(int player,JsonObject c,string how){var d=Row((int)N(c,"deed"));DropConfront(player,S(c,"npc"));if(d==null)return;var witnesses=A(JsonNode.Parse(S(d,"witnesses","[]"))).Select(w=>w!.GetValue<string>()).Append(S(c,"npc")).ToList();if(N(d,"owner_saw")>0)witnesses.Add(S(d,"owner"));if(N(d,"quiet")>0)Spread(player,d,witnesses);C.Log(player,"caught_stealing",S(c,"npc"),"Jef was caught stealing and "+how+".");Memory(player,S(c,"npc"),"I caught Jef thieving, and he "+how+". I went for the police.",7,"Jef was caught stealing",-2);Schedule(player,(int)N(d,"id"),6);}
    private JsonObject LeaveConfront(int player,string id){var c=Confronts(player).FirstOrDefault(c=>S(c,"npc")==id)as JsonObject;if(c==null)return new(){["left"]=false,["text"]=""};Escalate(player,c,"would not stop to answer for it");return new(){["left"]=true,["text"]=$"Thief! Stop, thief! {Name(id)} shouts after you and runs for the police."};}
    private void ConfrontTick(int player){foreach(var c in Confronts(player)){var row=Row((int)N(c,"deed"));if(!LiveConfront(c!.AsObject(),row))DropConfront(player,S(c,"npc"));else if(Minute-N(c,"at")>30)Escalate(player,c.AsObject(),"walked off before it was settled");}}
    private JsonObject Noticed(int player,int deed,string who)
    {
        var suspects=A(State(player,"deed_suspects"));var entry=suspects.FirstOrDefault(s=>N(s,"deed")==deed&&N(s,"until")>=Minute&&A(s?["ids"]).Any(i=>i?.GetValue<string>()==who));var d=Row(deed);if(entry==null||d==null||S(d,"status")!="open"||N(d,"player_id",1)!=player)return new(){["hit"]=false};entry["ids"]=new JsonArray(A(entry["ids"]).Where(i=>i?.GetValue<string>()!=who).Select(i=>i!.DeepClone()).ToArray());C.SetPlayerState(player,"deed_suspects",suspects);var saw=A(JsonNode.Parse(S(d,"witnesses","[]")));if(!saw.Any(i=>i?.GetValue<string>()==who))saw.Add(who);C.Execute("UPDATE deed SET seen=1,owner_saw=MAX(owner_saw,$p0),witnesses=$p1,rumour_at=NULL WHERE id=$p2",S(d,"owner")==who?1:0,saw.ToJsonString(),deed);var result=Reactions(player,deed,new JsonArray(new JsonObject{["id"]=who,["d"]=8,["los"]=true,["facing"]=1,["owner"]=S(d,"owner")==who}));result["hit"]=true;result["deed"]=deed;result["text"]=S(result["reaction"],"line",Name(who)+" knows what you did.");return result;
    }
    private JsonArray Watchers(int player)
    {
        var result=new JsonArray();foreach(var d in C.Rows("SELECT * FROM deed WHERE player_id=$p0 AND seen=1 AND quiet=0 AND status IN ('open','returned') AND day>=$p1",player,Day-2)){if(N(d,"owner_saw")>0&&!result.Any(w=>w?.GetValue<string>()==S(d,"owner")))result.Add(S(d,"owner"));foreach(var w in A(JsonNode.Parse(S(d,"witnesses","[]"))))if(!result.Any(n=>n?.GetValue<string>()==w?.GetValue<string>()))result.Add(w!.DeepClone());}return new JsonArray(result.Take(24).Select(w=>w!.DeepClone()).ToArray());
    }
    private JsonObject Recognise(NativeServiceRequest r)
