        string id=r.Text("id");double d=N(r.Body,"d",double.NaN),x=N(r.Body,"x",double.NaN),z=N(r.Body,"z",double.NaN);if(!Finite(d,x,z)||d>10||!Watchers(r.PlayerId).Any(w=>w?.GetValue<string>()==id))return new(){["hit"]=false};var deed=C.Rows("SELECT * FROM deed WHERE player_id=$p0 AND seen=1 AND quiet=0 AND status IN ('open','returned') AND day>=$p1 ORDER BY id DESC",r.PlayerId,Day-2).FirstOrDefault(row=>S(row,"owner")==id&&N(row,"owner_saw")>0||A(JsonNode.Parse(S(row,"witnesses","[]"))).Any(w=>w?.GetValue<string>()==id));if(deed==null)return new(){["hit"]=false};var done=State(r.PlayerId,"recognised")as JsonObject??new();var ids=A(done[id]);int number=(int)N(deed,"id");if(ids.Any(n=>V(n)==number))return new(){["hit"]=false};ids.Add(number);done[id]=new JsonArray(ids.TakeLast(6).Select(n=>n!.DeepClone()).ToArray());C.SetPlayerState(r.PlayerId,"recognised",done);var resident=Resident(id);double chance=Math.Min(1,1.2*SeeChance(Math.Max(0,d),r.Bool("los"),Math.Clamp(N(r.Body,"facing"),-1,1),S(deed,"owner")==id,Light(x,z,false),false,Sight,S(resident,"trade"),(int)N(resident,"age",40)));if(C.Roll()>=chance)return new(){["hit"]=false};Memory(r.PlayerId,id,"I saw Jef again in the street, the thief, bold as brass.",5,"Jef was about again after he stole",-1);Schedule(r.PlayerId,number,6);return new(){["hit"]=true,["deed"]=number,["text"]=$"{Name(id)} points at you: That is him! That is the thief!"};
    }
